import { Routes } from "@angular/router";
import { ListSesionComponent } from "./list-sesion/list-sesion.component";
import { FormSesionComponent } from "./form-sesion/form-sesion.component";

export const sesionesRoutes:Routes=[
    { path: '', redirectTo: 'list', pathMatch: 'full' },
    { path: 'list', component: ListSesionComponent },
    { path: 'nuevo', component: FormSesionComponent },
    { path: 'editar/:sesion_id', component: FormSesionComponent }
]