import { Component } from '@angular/core';
import { Form, GenericFormComponent } from '../../../shared/generic-form/generic-form.component';
import { Sesion } from '../../../models/sesion.model';
import { SesionService } from '../../../controllers/sesion.service';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../services/utils.service';

import { FileInputComponent } from '../../../shared/file-input/file-input.component';
import { FormsModule } from '@angular/forms';
import { FormSesionDocumentoComponent } from './form-sesion-documento/form-sesion-documento.component';
import { SesionDocumento } from '../../../models/sesion.documento';

@Component({
    selector: 'app-form-sesion',
    imports: [
    FormsModule,
    FormSesionDocumentoComponent
],
    templateUrl: './form-sesion.component.html',
    styleUrl: './form-sesion.component.css'
})
export class FormSesionComponent {
  new:Partial<Sesion>={}
  edit?:Sesion
  constructor(
    public sesionController:SesionService,
    private route: ActivatedRoute,
    private utils: UtilsService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const id= this.utils.intOrNull(params.get('sesion_id'))
      if(id){
        this.edit=await this.sesionController.find(id, ['sesionesDocumentos'])
        if(this.edit){
          this.new=this.edit
        }
      }
    })
  }

  async submit(){
    this.edit= await this.sesionController.createOrUpdate(this.new)
  }

  addDocumento(){
    if(!this.edit) return
    if(!this.edit?.sesiones_documentos){
      this.edit.sesiones_documentos=[]
    }
    this.edit?.sesiones_documentos.push({
      sesion_id: 0,
      archivo_url: '',
      formato: 'PDF',
      tipo_documento: 'MINUTA',
      comentario: '',
      usuario_id: 0,
      id: 0,
      deleted_at: null,
      created_at: '',
      updated_at: null
    })
  }

  onDocDeleted(doc:SesionDocumento){
    if(!this.edit){
      return
    }
    const index = this.edit.sesiones_documentos?.indexOf(doc)
    if(index && index>-1){
      this.edit.sesiones_documentos?.splice(index,1)
    }
  }
}
