import { Component, EventEmitter, Input, Output } from '@angular/core';
import { SesionDocumento } from '../../../../models/sesion.documento';
import { ApiServiceService } from '../../../../services/api/api-service.service';

import { UtilsService } from '../../../../services/utils.service';
import { FormsModule } from '@angular/forms';
import { firstValueFrom } from 'rxjs';
import { SesionDocumentoService } from '../../../../controllers/sesion.documento.service';

@Component({
    selector: 'app-form-sesion-documento',
    imports: [
    FormsModule
],
    templateUrl: './form-sesion-documento.component.html',
    styleUrl: './form-sesion-documento.component.css'
})
export class FormSesionDocumentoComponent {
  id?:number
  @Input() sesion_id!:number;
  @Input() edit!:SesionDocumento;
  file:File|null=null
  constructor(
    private api:ApiServiceService,
    public utils:UtilsService,
    private sesionDocumentoController: SesionDocumentoService,
  ){}
  @Output() deleted = new EventEmitter()

  appendFile(event: Event){
    this.file= this.utils.fileFromInputEvent(event)
  }

  async submit(){
    const data= new FormData()
    data.append('id', this.sesion_id.toString())
    data.append('tipo', this.edit.tipo_documento)
    data.append('comentario', this.edit.comentario)
    if(this.file){
      data.append('document', this.file)
    }
    if(this.edit.id>0){
      data.append('sesiones_documento_id', this.edit.id.toString())
    }
    const res = await firstValueFrom(this.api.postFormData<SesionDocumento>('api/files/sesiones/documento/save',data))
    if(res.data){
      this.edit=res.data
    }
    console.log(res)
  }

  async delete(){
    if(this.edit.id>0){
      const res =await this.sesionDocumentoController.switch(this.edit.id)
      if(res){
        this.deleted.emit()
      }
      return 
    }
    this.deleted.emit()
  }
}
